"""Generate the root README.md gallery linking to all CAD projects and their previews."""

from __future__ import annotations

from pathlib import Path

_HEADER = """# CodeCad

Parametric 3D CAD models (`build123d`) for FDM 3D printing.

<!-- AUTO-GENERATED by generate_readme.py — do not edit manually. -->
"""


def _format_image_html(root: Path, image_path: Path, alt_text: str) -> str:
    if not image_path.is_file():
        return f"<em>{alt_text}: not generated</em>"
    rel = image_path.relative_to(root).as_posix()
    return f'<a href="{rel}"><img src="{rel}" alt="{alt_text}" width="49%"></a>'


def _format_project_section(root: Path, proj_dir: Path) -> str:
    name = proj_dir.name
    readme_path = proj_dir / "README.md"
    title_target = readme_path if readme_path.is_file() else proj_dir
    title_rel = title_target.relative_to(root).as_posix()

    heading = f"## [{name}]({title_rel})"
    script_path = proj_dir / f"{name}.py"
    if script_path.is_file():
        script_rel = script_path.relative_to(root).as_posix()
        heading += f" · [`{script_path.name}`]({script_rel})"

    preview_3d = _format_image_html(root, proj_dir / ".preview" / "preview.png", f"{name} 3D")
    preview_2d = _format_image_html(
        root, proj_dir / ".preview" / "preview_engineering.png", f"{name} 2D"
    )
    return f"{heading}\n\n<p>\n  {preview_3d}\n  {preview_2d}\n</p>"


def generate_root_readme(root: Path | None = None) -> Path:
    """Scan projects/ and write the root README.md with a project gallery."""
    repo_root = (root or Path(__file__).resolve().parent.parent).resolve()
    projects_dir = repo_root / "projects"

    sections: list[str] = []
    if projects_dir.is_dir():
        for child in sorted(projects_dir.iterdir(), key=lambda p: p.name.lower()):
            if not child.is_dir() or child.name.startswith("."):
                continue
            sections.append(_format_project_section(repo_root, child))

    body = "\n\n".join(sections) + "\n" if sections else ""
    content = f"{_HEADER}\n{body}" if body else _HEADER
    readme_path = repo_root / "README.md"
    readme_path.write_text(content, encoding="utf-8")
    return readme_path
